// FS TV MODE — navigasi remote (D-pad) + tampilan 10-foot untuk Android TV.
// Dipakai di semua halaman (index, hiburan, dst). Aktif otomatis kalau
// user-agent TV terdeteksi, atau kalau member menekan tombol "📺 TV".
// Pilihan tersimpan di localStorage 'fsTVMode' ('1'/'0'); ?tv=1 / ?tv=0
// memaksa sekali jalan. Di luar Mode TV, file ini tidak mengubah apa pun.
(function () {
  'use strict';

  var KEY = 'fsTVMode';
  var root = document.documentElement;

  function ua() { try { return navigator.userAgent || ''; } catch (e) { return ''; } }

  function isTVUA() {
    return /(android tv|google tv|smart[- ]?tv|aft[A-Z0-9]*|bravia|hbbtv|netcast|webos|tizen|viera|aquos|roku|fire tv|droidlogic|amlogic|opera tv|mibox|mi box|shield|b860h|s905|rk33|h96|tx3|mecool|ugoos|beelink|tanix|x96|hk1|\batv[0-9])/i.test(ua());
  }

  // Heuristik box Android TV generik: user-agent-nya sering polos tanpa kata
  // "TV" (mis. "Linux; Android 11; B860H ... wv"). Yang membedakan TV dari
  // HP/tablet Android: layar lebar + tidak ada sentuhan + tidak ada hover.
  // HP/tablet selalu punya sentuhan -> tidak kena. Laptop bukan Android.
  function isLikelyTV() {
    if (!/android/i.test(ua())) return false;
    var w = 0;
    try {
      w = Math.max(window.screen ? window.screen.width : 0, window.innerWidth || 0);
    } catch (e) {}
    if (w < 1280) return false;
    var touch = false;
    try { touch = (navigator.maxTouchPoints || 0) > 0 || 'ontouchstart' in window; } catch (e) {}
    if (touch) return false;
    try {
      if (window.matchMedia) {
        return window.matchMedia('(hover: none)').matches || window.matchMedia('(pointer: none)').matches;
      }
    } catch (e) {}
    return true;
  }

  function param(name) {
    try {
      var m = new RegExp('[?&]' + name + '=([^&]*)').exec(location.search || '');
      return m ? decodeURIComponent(m[1]) : null;
    } catch (e) { return null; }
  }

  function stored() {
    try { return localStorage.getItem(KEY); } catch (e) { return null; }
  }

  function shouldBeTV() {
    var p = param('tv');
    if (p === '1') return true;
    if (p === '0') return false;
    var s = stored();
    if (s === '1') return true;
    if (s === '0') return false;
    return isTVUA() || isLikelyTV();
  }

  // --- tombol toggle "📺 TV" (selalu ada, di semua halaman) ---
  function ensureToggle() {
    var b = document.getElementById('fsTvToggle');
    if (b) return b;
    b = document.createElement('button');
    b.id = 'fsTvToggle';
    b.type = 'button';
    b.setAttribute('aria-label', 'Mode TV untuk remote Android TV');
    b.addEventListener('click', function () { setTV(!root.classList.contains('tv-mode'), true); });
    document.body.appendChild(b);
    syncToggle();
    return b;
  }

  function syncToggle() {
    var b = document.getElementById('fsTvToggle');
    if (!b) return;
    var on = root.classList.contains('tv-mode');
    b.textContent = on ? '📺 TV: ON' : '📺 TV';
    b.setAttribute('aria-pressed', on ? 'true' : 'false');
  }

  // --- kursor ala Netflix: highlight mengambang yang meluncur halus ---
  // Bukan outline bawaan (yang loncat instan), tapi satu kotak emas yang
  // mengikuti elemen terfokus dengan transisi CSS + kartu ikut membesar.
  var cursorEl = null;
  var cursorTarget = null;
  var cursorRecheck = null;

  function ensureCursor() {
    var c = document.getElementById('fsTvCursor');
    if (c) { cursorEl = c; return c; }
    c = document.createElement('div');
    c.id = 'fsTvCursor';
    c.setAttribute('aria-hidden', 'true');
    document.body.appendChild(c);
    cursorEl = c;
    return c;
  }

  function positionCursor() {
    if (!root.classList.contains('tv-mode')) return;
    var c = ensureCursor();
    var el = document.activeElement;
    if (!el || el === document.body || !el.getBoundingClientRect) { c.style.display = 'none'; return; }
    var r = el.getBoundingClientRect();
    if (r.width === 0 && r.height === 0) { c.style.display = 'none'; return; }
    var pad = 7;
    c.style.display = 'block';
    c.style.left = (r.left - pad) + 'px';
    c.style.top = (r.top - pad) + 'px';
    c.style.width = (r.width + pad * 2) + 'px';
    c.style.height = (r.height + pad * 2) + 'px';
    if (cursorTarget && cursorTarget !== el) cursorTarget.classList.remove('fs-tv-focus');
    var isNew = cursorTarget !== el;
    cursorTarget = el;
    var tag = (el.tagName || '').toUpperCase();
    if (tag !== 'INPUT' && tag !== 'TEXTAREA' && tag !== 'SELECT' && !el.isContentEditable) {
      el.classList.add('fs-tv-focus');
    }
    // Kartu membesar pakai transisi 0.18s; baca ulang rect sekali setelah
    // selesai supaya kursor membungkus ukuran akhirnya, bukan sebelum scale.
    // Hanya dijadwalkan saat target baru (bukan tiap pemanggilan) supaya
    // tidak jadi timer berulang.
    if (isNew) {
      if (cursorRecheck) clearTimeout(cursorRecheck);
      cursorRecheck = setTimeout(function () { cursorRecheck = null; if (document.activeElement === el) positionCursor(); }, 200);
    }
  }

  function hideCursor() {
    if (cursorTarget) { cursorTarget.classList.remove('fs-tv-focus'); cursorTarget = null; }
    if (cursorEl) cursorEl.style.display = 'none';
  }

  // --- kartu <div onclick> dijadikan bisa difokus remote ---
  // PENTING (bug TV Mode v2, 23 Nov 2026): semua kartu film/musik/anime/TV
  // di hiburan.html dibuat lewat JS dengan `card.onclick = function(){...}`
  // (29x) — itu TIDAK membuat atribut onclick, jadi cek hasAttribute saja
  // tidak pernah kena dan kartu tidak pernah dapat tabindex: kursor remote
  // tidak bisa diarahkan ke kartu sama sekali. Cek juga properti .onclick.
  function isClickable(el) {
    if (!el || el.nodeType !== 1) return false;
    try { if (typeof el.onclick === 'function') return true; } catch (e) {}
    try { if (el.hasAttribute && el.hasAttribute('onclick')) return true; } catch (e) {}
    return false;
  }
  function makeFocusable(el) {
    if (!el.hasAttribute('tabindex')) {
      el.setAttribute('tabindex', '0');
      el.setAttribute('role', 'button');
    }
  }
  function enhance(el) {
    if (!el || el.nodeType !== 1) return;
    if (isClickable(el)) makeFocusable(el);
    if (el.querySelectorAll) {
      var list = el.querySelectorAll('*');
      for (var i = 0; i < list.length; i++) {
        if (isClickable(list[i])) makeFocusable(list[i]);
      }
    }
  }

  var observer = null;
  function watchCards() {
    if (observer || !window.MutationObserver) return;
    observer = new MutationObserver(function (muts) {
      for (var i = 0; i < muts.length; i++) {
        var added = muts[i].addedNodes;
        for (var j = 0; j < added.length; j++) enhance(added[j]);
      }
    });
    observer.observe(document.body, { childList: true, subtree: true });
  }

  // --- daftar elemen yang bisa difokus ---
  function focusables() {
    var sel = 'a[href], button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])';
    var all = document.querySelectorAll(sel);
    var out = [];
    for (var i = 0; i < all.length; i++) {
      var el = all[i];
      if (el.closest('[hidden]')) continue;
      var r = el.getBoundingClientRect();
      // display:none = rect nol. Jangan pakai offsetParent: elemen di dalam
      // ancestor position:fixed (sidebar, modal detail) offsetParent-nya null
      // padahal terlihat dan harus bisa difokus remote.
      if (r.width === 0 && r.height === 0) continue;
      var vis = null;
      try { vis = getComputedStyle(el).visibility; } catch (e) {}
      if (vis === 'hidden') continue;
      out.push(el);
    }
    return out;
  }

  // --- navigasi spasial: panah pindah ke elemen terdekat di arah itu ---
  function move(dir) {
    var cur = document.activeElement;
    var els = focusables();
    if (!els.length) return;
    if (!cur || cur === document.body || els.indexOf(cur) === -1) {
      els[0].focus();
      try { els[0].scrollIntoView({ block: 'nearest', inline: 'nearest', behavior: 'smooth' }); } catch (e) {}
      positionCursor();
      return;
    }
    var r = cur.getBoundingClientRect();
    var cx = r.left + r.width / 2, cy = r.top + r.height / 2;
    var best = null, bestScore = Infinity;
    for (var i = 0; i < els.length; i++) {
      var el = els[i];
      if (el === cur) continue;
      var b = el.getBoundingClientRect();
      var ex = b.left + b.width / 2, ey = b.top + b.height / 2;
      var dx = ex - cx, dy = ey - cy;
      var primary, secondary;
      if (dir === 'left') { if (dx > -4) continue; primary = -dx; secondary = Math.abs(dy); }
      else if (dir === 'right') { if (dx < 4) continue; primary = dx; secondary = Math.abs(dy); }
      else if (dir === 'up') { if (dy > -4) continue; primary = -dy; secondary = Math.abs(dx); }
      else { if (dy < 4) continue; primary = dy; secondary = Math.abs(dx); }
      // Kerucut arah: jangan lompat ke elemen yang jauh menyamping.
      if (secondary > primary * 1.5 + 80) continue;
      var score = primary + secondary * 2.5;
      if (score < bestScore) { bestScore = score; best = el; }
    }
    // Kalau tidak ada yang lolos kerucut (mis. baris berikutnya agak miring),
    // jangan biarkan panah mati: ambil yang terdekat di arah itu apa pun.
    if (!best) {
      bestScore = Infinity;
      for (var j = 0; j < els.length; j++) {
        var el2 = els[j];
        if (el2 === cur) continue;
        var b2 = el2.getBoundingClientRect();
        var ex2 = b2.left + b2.width / 2, ey2 = b2.top + b2.height / 2;
        var dx2 = ex2 - cx, dy2 = ey2 - cy;
        var p2, s2;
        if (dir === 'left') { if (dx2 > -4) continue; p2 = -dx2; s2 = Math.abs(dy2); }
        else if (dir === 'right') { if (dx2 < 4) continue; p2 = dx2; s2 = Math.abs(dy2); }
        else if (dir === 'up') { if (dy2 > -4) continue; p2 = -dy2; s2 = Math.abs(dx2); }
        else { if (dy2 < 4) continue; p2 = dy2; s2 = Math.abs(dx2); }
        var score2 = p2 + s2 * 2.5;
        if (score2 < bestScore) { bestScore = score2; best = el2; }
      }
    }
    if (best) {
      best.focus();
      try { best.scrollIntoView({ block: 'nearest', inline: 'nearest', behavior: 'smooth' }); } catch (e) {}
      positionCursor();
    }
  }

  function isTyping(el) {
    if (!el) return false;
    var t = (el.tagName || '').toUpperCase();
    return t === 'INPUT' || t === 'TEXTAREA' || t === 'SELECT' || el.isContentEditable;
  }

  function closeTopModal() {
    // Jangan pakai offsetParent: overlay position:fixed offsetParent-nya null
    // padahal terlihat. Cek display + rect saja.
    var det = document.getElementById('fsADetail');
    if (det && det.style.display !== 'none' && det.getBoundingClientRect().width > 0) {
      det.style.display = 'none';
      return true;
    }
    var cin = document.getElementById('fsCinemaDetail');
    if (cin && cin.style.display !== 'none' && cin.getBoundingClientRect().width > 0) {
      try {
        if (typeof window.fsCinemaCloseDetail === 'function') window.fsCinemaCloseDetail();
        else cin.style.display = 'none';
      } catch (e) { cin.style.display = 'none'; }
      return true;
    }
    var side = document.getElementById('sidebar');
    if (side && side.classList.contains('active')) {
      side.classList.remove('active');
      return true;
    }
    return false;
  }

  function onKey(e) {
    if (!root.classList.contains('tv-mode')) return;
    var k = e.key;
    var t = e.target;
    if (k === 'Escape' || k === 'BrowserBack') {
      if (isTyping(t)) { try { t.blur(); } catch (err) {} return; }
      if (closeTopModal()) { e.preventDefault(); e.stopPropagation(); }
      return;
    }
    if (isTyping(t)) return; // Panah di kolom teks = gerak kursor, jangan dibajak.
    if (k === 'ArrowLeft' || k === 'ArrowRight' || k === 'ArrowUp' || k === 'ArrowDown') {
      e.preventDefault(); e.stopPropagation();
      move(k === 'ArrowLeft' ? 'left' : k === 'ArrowRight' ? 'right' : k === 'ArrowUp' ? 'up' : 'down');
      return;
    }
    if (k === 'Enter' || k === ' ') {
      var el = document.activeElement;
      if (!el || el === document.body) return;
      var tag = (el.tagName || '').toUpperCase();
      // Tombol/link/input sudah ditangani browser; kartu div perlu klik manual.
      if (tag === 'DIV' || el.getAttribute('role') === 'button') {
        e.preventDefault(); e.stopPropagation();
        el.click();
      }
    }
  }

  function focusFirst() {
    var els = focusables();
    var strip = document.querySelector('.fs-tabstrip button');
    var target = strip || els[0];
    if (target) {
      try { target.focus(); target.scrollIntoView({ block: 'nearest', inline: 'nearest', behavior: 'smooth' }); } catch (e) {}
      positionCursor();
    }
  }

  function setTV(on, save) {
    if (on) {
      root.classList.add('tv-mode');
      enhance(document.body);
      watchCards();
      if (save) { try { localStorage.setItem(KEY, '1'); } catch (e) {} }
      syncToggle();
      setTimeout(focusFirst, 350);
      setTimeout(positionCursor, 500);
    } else {
      root.classList.remove('tv-mode');
      hideCursor();
      if (save) { try { localStorage.setItem(KEY, '0'); } catch (e) {} }
      syncToggle();
    }
  }

  function init() {
    ensureToggle();
    if (shouldBeTV()) setTV(true, false);
    document.addEventListener('keydown', onKey, true);
    // Kursor ikut setiap perpindahan fokus (termasuk fokus native WebView).
    document.addEventListener('focusin', function () { positionCursor(); });
    // Saat halaman bergeser (scroll halus), kursor ikut bergeser.
    var scrollT = null;
    window.addEventListener('scroll', function () {
      if (!root.classList.contains('tv-mode')) return;
      if (scrollT) return;
      scrollT = setTimeout(function () { scrollT = null; positionCursor(); }, 60);
    }, true);
    window.addEventListener('resize', function () { positionCursor(); });
    window.FS_TV = { setTV: setTV, isTV: function () { return root.classList.contains('tv-mode'); } };
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();

// ===== FS DONASI QRIS (24 Nov 2026, perintah San) =====
// Popup donasi sekali saat kunjungan pertama, di SEMUA halaman (file ini
// dimuat 9 halaman). QRIS asli San (GoPay merchant FREEDOM SYNDICATE,
// DIGITA, NMID ID1026530363948) di-inline sebagai data URI di bawah —
// BUKAN file terpisah — karena push-files menolak konten biner dan
// create_or_update_file hanya menerima teks, jadi gambar tidak bisa
// dikirim sebagai images/qris-donasi.png lewat jalur push biasa.
// REVISI 24 Nov 2026 (perintah San): banner biru "gopay merchant" di
// atas di-crop (potong 310 px dari atas, gambar jadi 1200x1390, JPEG
// q85). Strip bawah (bank-bank) dibiarkan. QR TIDAK diubah isinya:
// payload hasil decode sebelum dan sesudah crop IDENTIK (215 karakter,
// merchant + NMID sama) — tetap bisa di-scan ke merchant yang sama.
// Kalau suatu hari gambar perlu diganti, ganti string FS_QRIS_IMG ini
// dengan base64 file baru.
// Perilaku: tampil 1,2 dtk setelah halaman siap, hanya kalau
// localStorage 'fsDonasiShown' belum ada; begitu tampil, flag langsung
// disetel (tampil sekali per browser). Tutup via ✕, tombol "Nanti saja",
// klik latar, atau Esc. TIDAK tampil di Mode TV (remote tidak bisa
// menutup popup dengan nyaman). window.fsDonasiShow() = tampilkan lagi
// manual (untuk tes / tautan Donasi di menu nanti).
(function () {
  'use strict';
  var KEY = 'fsDonasiShown';
  var FS_QRIS_IMG = 'data:image/jpeg;base64,';

  function shown() {
    try { return localStorage.getItem(KEY) === '1'; } catch (e) { return false; }
  }
  function markShown() {
    try { localStorage.setItem(KEY, '1'); } catch (e) {}
  }
  function isTV() {
    try { return document.documentElement.classList.contains('tv-mode'); } catch (e) { return false; }
  }
  function hidePop() {
    var p = document.getElementById('fsDonasiPop');
    if (p) p.remove();
    try { document.body.style.overflow = ''; } catch (e) {}
    try { document.removeEventListener('keydown', onKey, true); } catch (e) {}
  }
  function onKey(e) {
    if (e.key === 'Escape') hidePop();
  }
  function showPop() {
    if (shown() || isTV() || document.getElementById('fsDonasiPop') || !document.body) return;
    markShown();
    var pop = document.createElement('div');
    pop.id = 'fsDonasiPop';
    pop.setAttribute('role', 'dialog');
    pop.setAttribute('aria-label', 'Donasi untuk FREEDOM SYNDICATE');
    pop.style.cssText = 'position:fixed;inset:0;z-index:10000;background:rgba(2,6,23,0.82);display:flex;align-items:center;justify-content:center;padding:16px;';
    pop.innerHTML =
      '<div style="position:relative;width:100%;max-width:340px;max-height:92vh;overflow-y:auto;background:#0f172a;border:1px solid rgba(232,169,12,0.45);border-radius:18px;padding:20px 18px 16px;box-shadow:0 16px 48px rgba(0,0,0,0.65);text-align:center;">'
      + '<button id="fsDonasiClose" type="button" aria-label="Tutup" style="position:absolute;top:8px;right:12px;background:none;border:0;color:#94A3B8;font-size:1.25rem;cursor:pointer;line-height:1;font-family:inherit;">✕</button>'
      + '<div style="font-size:1.05rem;font-weight:900;color:#fff;line-height:1.3;padding-right:20px;">💛 Dukung FREEDOM SYNDICATE</div>'
      + '<div style="font-size:0.8rem;color:#CBD5E1;line-height:1.6;margin-top:8px;">Semua yang ada di sini &mdash; situs, bot, dan konten &mdash; gratis untuk semua member. Tapi server dan operasionalnya tetap butuh biaya. Kalau berkenan, donasi seikhlasnya lewat QRIS di bawah ini.</div>'
      + '<img src="' + FS_QRIS_IMG + '" alt="Kode QRIS donasi FREEDOM SYNDICATE" style="display:block;width:100%;max-width:272px;margin:14px auto 6px;border-radius:12px;border:1px solid rgba(255,255,255,0.15);">'
      + '<div style="font-size:0.68rem;color:#94A3B8;line-height:1.5;">Nominal bebas &mdash; scan pakai GoPay, BCA, Mandiri, BNI, BRI, atau aplikasi apa saja.<br>Terima kasih, semoga rezekinya dilancarkan. 🙏</div>'
      + '<button id="fsDonasiLater" type="button" style="margin-top:14px;width:100%;background:#E8A90C;color:#0D0C0A;border:0;border-radius:10px;padding:12px;font-weight:900;font-size:0.88rem;cursor:pointer;font-family:inherit;">Nanti saja</button>'
      + '</div>';
    pop.addEventListener('click', function (e) { if (e.target === pop) hidePop(); });
    document.body.appendChild(pop);
    try { document.body.style.overflow = 'hidden'; } catch (e) {}
    document.getElementById('fsDonasiClose').addEventListener('click', hidePop);
    document.getElementById('fsDonasiLater').addEventListener('click', hidePop);
    document.addEventListener('keydown', onKey, true);
  }
  window.fsDonasiShow = function () {
    try { localStorage.removeItem(KEY); } catch (e) {}
    showPop();
  };
  function init() {
    if (shown() || isTV()) return;
    setTimeout(showPop, 1200);
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
